def _select_input_format(requested: str, tool_inputs: Mapping[str, Any]) -> str:
    if requested in {"legacy", "21.01"}:
        return requested
    if requested != "auto":
        raise ValueError("input_format must be 'auto', 'legacy', or '21.01'")
    if any("|" in str(key) for key in tool_inputs):
        return "legacy"
    return "21.01"


